int sock_recv(int fd, void __user *ubuf, size_t size, unsigned int flags,
              struct sockaddr __user *addr, int __user *addr_len) {
  struct socket *sock;
  struct msghdr msg;
  struct iovec iov;
  int ret;

  if (fd < 0 || !ubuf || !size)
    return -EINVAL;

  sock = fd_getsock(fd);
  if (IS_ERR(sock))
    return PTR_ERR(sock);

  iov.iov_base = ubuf;
  iov.iov_len = size;
  msg.msg_name = addr;
  msg.msg_namelen = addr_len ? get_user(*addr_len, addr_len) : 0;
  msg.msg_iov = &iov;
  msg.msg_iovlen = 1;
  msg.msg_control = NULL;
  msg.msg_controllen = 0;
  msg.msg_flags = flags;

  ret = sock->ops->recvmsg(sock, &msg, msg.msg_flags);
  if (ret > 0 && msg.msg_namelen && addr && addr_len) {
    put_user(msg.msg_namelen, addr_len);
  }

  sock_put(sock);
  return ret;
}

int sock_recvmsg(int fd, void __user *ubuf, size_t size, unsigned int flags,
                 struct sockaddr __user *addr, int __user *addr_len) {
    struct socket *sock;
    struct msghdr msg;
    struct iovec iov;
    int ret, len;

    if (!ubuf || size == 0) {
        return -EINVAL;
    }

    sock = sockfd_lookup(fd, &ret);
    if (!sock) {
        return ret;
    }

    iov.iov_base = ubuf;
    iov.iov_len = size;

    msg.msg_name = addr;
    msg.msg_namelen = sizeof(struct sockaddr);
    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;
    msg.msg_control = NULL;
    msg.msg_controllen = 0;
    msg.msg_flags = flags;

    ret = sock->ops->recvmsg(NULL, sock, &msg, size, flags, NULL);
    if (ret < 0) {
        goto out;
    }

    len = ret;
    if (addr && msg.msg_namelen > 0) {
        ret = put_user(msg.msg_namelen, addr_len);
        if (ret < 0) {
            goto out;
        }
    }

out:
    sockfd_put(sock);
    return ret;
}

int sock_recv(int fd, void __user *ubuf, size_t size, unsigned int flags,
              struct sockaddr __user *addr, int __user *addr_len) {
    struct socket *sock;
    struct msghdr msg;
    struct iovec iov;
    int ret;

    if (size == 0)
        return -EINVAL;

    sock = sockfd_lookup(fd, &ret);
    if (!sock)
        return ret;

    iov.iov_base = ubuf;
    iov.iov_len = size;
    msg.msg_name = addr;
    msg.msg_namelen = addr ? sizeof(*addr) : 0;
    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;
    msg.msg_control = NULL;
    msg.msg_controllen = 0;
    msg.msg_flags = flags;

    ret = sock->ops->recvmsg(sock, &msg, msg.msg_flags);

    if (ret > 0 && addr && put_user(msg.msg_namelen, addr_len))
        ret = -EFAULT;

    sockfd_put(sock);
    return ret;
}

