int recvfrom(int fd, void __user *ubuf, size_t size, unsigned int flags,
             struct sockaddr __user *addr, int __user *addr_len) {
    struct socket *sock;
    struct msghdr msg;
    struct iovec iov;
    int ret;

    if (fd < 0 || fd >= NR_FILE)
        return -EBADF;

    sock = sockfd_lookup(fd, &ret);
    if (!sock)
        return ret;

    iov.iov_base = ubuf;
    iov.iov_len = size;

    msg.msg_name = addr;
    msg.msg_namelen = addr ? sizeof(*addr) : 0;
    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;
    msg.msg_control = NULL;
    msg.msg_controllen = 0;
    msg.msg_flags = flags;

    ret = sock->ops->recvmsg(NULL, sock, &msg, size, flags, NULL);

    if (ret > 0 && msg.msg_namelen && addr && addr_len) {
        if (put_user(msg.msg_namelen, addr_len))
            ret = -EFAULT;
    }

    fput_light(sock->file, 1);
    return ret;
}
